import csv
import re
from collections import deque

def load_data():
    with open('/app/dataset/people_accounts.csv') as f:
        reader = csv.DictReader(f)
        people = {f"{r['first_name']} {r['last_name']}": int(r['account_balance']) for r in reader}

    with open('/app/dataset/genealogy_trees.txt') as f:
        lines = [line.rstrip('\r\n') for line in f]

    return people, lines

people, grid = load_data()

# Locate each person in the grid.
person_coords = {}
for full_name, bal in people.items():
    first, last = full_name.split(' ', 1)

    # 1. Single line match
    found = False
    for r in range(len(grid)):
        if full_name in grid[r]:
            c = grid[r].index(full_name)
            person_coords[full_name] = {
                'rows': [r],
                'cols': [c, c + len(full_name) - 1],
                'balance': bal,
                'name': full_name
            }
            found = True
            break
        pattern = re.compile(re.escape(first) + r'\s+' + re.escape(last))
        m = pattern.search(grid[r])
        if m:
            person_coords[full_name] = {
                'rows': [r],
                'cols': [m.start(), m.end() - 1],
                'balance': bal,
                'name': full_name
            }
            found = True
            break
    if found:
        continue

    # 2. Consecutive lines match
    for r in range(len(grid) - 1):
        if first in grid[r] and last in grid[r+1]:
            c1 = grid[r].index(first)
            c2 = grid[r+1].index(last)
            if abs(c1 - c2) < 20:
                person_coords[full_name] = {
                    'rows': [r, r+1],
                    'cols': [min(c1, c2), max(c1 + len(first) - 1, c2 + len(last) - 1)],
                    'balance': bal,
                    'name': full_name
                }
                found = True
                break
        if last in grid[r] and first in grid[r+1]:
            c1 = grid[r].index(last)
            c2 = grid[r+1].index(first)
            if abs(c1 - c2) < 20:
                person_coords[full_name] = {
                    'rows': [r, r+1],
                    'cols': [min(c1, c2), max(c1 + len(last) - 1, c2 + len(first) - 1)],
                    'balance': bal,
                    'name': full_name
                }
                found = True
                break

# Box bounds for each matched person - using while loops to fully expand
def find_box_bounds(full_name):
    loc = person_coords[full_name]
    r_min = min(loc['rows'])
    r_max = max(loc['rows'])
    c_min = loc['cols'][0]
    c_max = loc['cols'][1]

    top_row = r_min
    while top_row > 0:
        row_str = grid[top_row - 1]
        subset = row_str[max(0, c_min-3):min(len(row_str), c_max+4)]
        if any(char in '+-~_│|\\' for char in subset if char != ' '):
            top_row -= 1
            if any(char in '+-~_' for char in subset):
                break
        else:
            break

    bot_row = r_max
    while bot_row < len(grid) - 1:
        row_str = grid[bot_row + 1]
        subset = row_str[max(0, c_min-3):min(len(row_str), c_max+4)]
        if any(char in '+-~_│|/' for char in subset if char != ' '):
            bot_row += 1
            if any(char in '+-~_' for char in subset):
                break
        else:
            break

    left_col = c_min
    while left_col > 0:
        is_border = False
        for r in range(top_row, bot_row + 1):
            if left_col - 1 < len(grid[r]) and grid[r][left_col - 1] in '|│+':
                is_border = True
                break
        if is_border:
            left_col -= 1
            break
        left_col -= 1

    right_col = c_max
    while right_col < max(len(row) for row in grid) - 1:
        is_border = False
        for r in range(top_row, bot_row + 1):
            if right_col + 1 < len(grid[r]) and grid[r][right_col + 1] in '|│+':
                is_border = True
                break
        if is_border:
            right_col += 1
            break
        right_col += 1

    return {
        'top': top_row,
        'bottom': bot_row,
        'left': left_col,
        'right': right_col
    }

for p in person_coords:
    person_coords[p]['box'] = find_box_bounds(p)

def is_line_char(r, c):
    if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[r]):
        return False
    char = grid[r][c]
    if char == ' ':
        return False
    if char.isalnum():
        return False
    return True

coord_to_person = {}
for name, info in person_coords.items():
    box = info['box']
    for r in range(box['top'], box['bottom'] + 1):
        for c in range(box['left'], box['right'] + 1):
            coord_to_person[(r, c)] = name

# Find direct children of a person by ONLY going DOWN
def get_children(person_name):
    info = person_coords[person_name]
    box = info['box']
    bot = box['bottom']

    start_nodes = []
    for c in range(box['left'] - 1, box['right'] + 2):
        if is_line_char(bot + 1, c):
            start_nodes.append((bot + 1, c))

    children = set()
    visited = set(start_nodes)
    queue = deque(start_nodes)

    while queue:
        r, c = queue.popleft()

        if (r, c) in coord_to_person:
            other = coord_to_person[(r, c)]
            if other != person_name:
                children.add(other)
                continue

        for dr, dc in [(1, 0), (0, -1), (0, 1), (1, -1), (1, 1)]:
            nr, nc = r + dr, c + dc
            if is_line_char(nr, nc) and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))

        for dr, dc in [(1, 0), (0, -1), (0, 1)]:
            for jump in range(1, 4):
                nr, nc = r + dr * jump, c + dc * jump
                if is_line_char(nr, nc):
                    gap_all_spaces = True
                    for j in range(1, jump):
                        ir, ic = r + dr * j, c + dc * j
                        if ir >= 0 and ir < len(grid) and ic >= 0 and ic < len(grid[ir]):
                            if grid[ir][ic] != ' ':
