                        if ir >= 0 and ir < len(grid) and ic >= 0 and ic < len(grid[ir]):
                            if grid[ir][ic] != ' ':
                                gap_all_spaces = False
                                break
                    if gap_all_spaces:
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                        break

    return list(parents)

# Verify ancestors of Dawid Majtyka up to great-great-grandparent (Level 4)
curr = 'Dawid Majtyka'
print(f"Tracing ancestors of {curr}:")
for i in range(1, 5):
    parents = get_parent(curr)
    print(f"  Level {i} parent(s) of {curr}: {parents}")
    if parents:
        curr = parents[0]
    else:
        print("  No parents found.")
