import csv
import re
from collections import deque

def load_data():
    with open('/app/dataset/people_accounts.csv') as f:
        reader = csv.DictReader(f)
        people = {f"{r['first_name']} {r['last_name']}": int(r['account_balance']) for r in reader}

    with open('/app/dataset/genealogy_trees.txt') as f:
        lines = [line.rstrip('\r\n') for line in f]

    return people, lines

people, grid = load_data()

# Locate each person's name coordinates in the grid.
person_coords = {}
for full_name, bal in people.items():
    first, last = full_name.split(' ', 1)

    # 1. Single line match
    found = False
    for r in range(len(grid)):
        if full_name in grid[r]:
            c = grid[r].index(full_name)
            person_coords[full_name] = {
                'coords': [(r, col) for col in range(c, c + len(full_name))],
                'balance': bal,
                'name': full_name
            }
            found = True
            break
        pattern = re.compile(re.escape(first) + r'\s+' + re.escape(last))
        m = pattern.search(grid[r])
        if m:
            person_coords[full_name] = {
                'coords': [(r, col) for col in range(m.start(), m.end())],
                'balance': bal,
                'name': full_name
            }
            found = True
            break
    if found:
        continue

    # 2. Consecutive lines match
    for r in range(len(grid) - 1):
        if first in grid[r] and last in grid[r+1]:
            c1 = grid[r].index(first)
            c2 = grid[r+1].index(last)
            if abs(c1 - c2) < 20:
                coords = [(r, col) for col in range(c1, c1 + len(first))] + \
                         [(r+1, col) for col in range(c2, c2 + len(last))]
                person_coords[full_name] = {
                    'coords': coords,
                    'balance': bal,
                    'name': full_name
                }
                found = True
                break
        if last in grid[r] and first in grid[r+1]:
            c1 = grid[r].index(last)
            c2 = grid[r+1].index(first)
            if abs(c1 - c2) < 20:
                coords = [(r, col) for col in range(c1, c1 + len(last))] + \
                         [(r+1, col) for col in range(c2, c2 + len(first))]
                person_coords[full_name] = {
                    'coords': coords,
                    'balance': bal,
                    'name': full_name
                }
                found = True
                break

print(f"Matched {len(person_coords)} people positions in the grid.")

# Map coordinate (r, c) to person name
coord_to_person = {}
for name, info in person_coords.items():
    for r, c in info['coords']:
        coord_to_person[(r, c)] = name

def is_line_char(r, c):
    if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[r]):
        return False
    # If it is part of any person's name, it's traversable (as a target)
    if (r, c) in coord_to_person:
        return True
    char = grid[r][c]
    if char == ' ':
        return False
    if char.isalnum():
        return False
    return True

# Get direct children (only going down)
def get_children(person_name):
    info = person_coords[person_name]
    start_nodes = info['coords']

    children = set()
    visited = set(start_nodes)
    queue = deque(start_nodes)

    while queue:
        r, c = queue.popleft()

        # If we hit another person's name coordinates
        if (r, c) in coord_to_person:
            other = coord_to_person[(r, c)]
            if other != person_name:
                children.add(other)
                continue # Stop traversing once we hit a target person

        # Move to neighbors: only nr >= r (going down or staying on same row)
        for dr, dc in [(1, 0), (0, -1), (0, 1), (1, -1), (1, 1)]:
            nr, nc = r + dr, c + dc
            if is_line_char(nr, nc) and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))

        # Jump across small gaps of space to handle fragmentation
        for dr, dc in [(1, 0), (0, -1), (0, 1)]:
            for jump in range(1, 4):
                nr, nc = r + dr * jump, c + dc * jump
                if is_line_char(nr, nc):
                    gap_all_spaces = True
                    for j in range(1, jump):
                        ir, ic = r + dr * j, c + dc * j
                        if ir >= 0 and ir < len(grid) and ic >= 0 and ic < len(grid[ir]):
                            if grid[ir][ic] != ' ' and (ir, ic) not in coord_to_person:
                                gap_all_spaces = False
                                break
                    if gap_all_spaces:
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                        break

    return list(children)

# Get direct parent (only going up)
def get_parent(person_name):
    info = person_coords[person_name]
    start_nodes = info['coords']

    parents = set()
    visited = set(start_nodes)
    queue = deque(start_nodes)

    while queue:
        r, c = queue.popleft()

        if (r, c) in coord_to_person:
            other = coord_to_person[(r, c)]
            if other != person_name:
                parents.add(other)
                continue

        # Move to neighbors: only nr <= r (going up or staying on same row)
        for dr, dc in [(-1, 0), (0, -1), (0, 1), (-1, -1), (-1, 1)]:
            nr, nc = r + dr, c + dc
            if is_line_char(nr, nc) and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))

        # Jump across small gaps of space
        for dr, dc in [(-1, 0), (0, -1), (0, 1)]:
            for jump in range(1, 4):
                nr, nc = r + dr * jump, c + dc * jump
                if is_line_char(nr, nc):
                    gap_all_spaces = True
                    for j in range(1, jump):
                        ir, ic = r + dr * j, c + dc * j
                        if ir >= 0 and ir < len(grid) and ic >= 0 and ic < len(grid[ir]):
                            if grid[ir][ic] != ' ' and (ir, ic) not in coord_to_person:
                                gap_all_spaces = False
                                break
                    if gap_all_spaces:
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                        break

    return list(parents)

# Verify ancestors of Dawid Majtyka up to great-great-grandparent (Level 4)
curr = 'Dawid Majtyka'
print(f"Tracing ancestors of {curr}:")
for i in range(1, 5):
    parents = get_parent(curr)
    print(f"  Level {i} parent(s) of {curr}: {parents}")
    if parents:
        curr = parents[0]
    else:
        print("  No parents found.")
        break

gg_grandparent = curr
print(f"\nGreat-great-grandparent of Dawid Majtyka: {gg_grandparent}")
children = get_children(gg_grandparent)
print(f"Direct children of {gg_grandparent}: {children}")

for child in children:
    child_children = get_children(child)
    grandchildren = []
    for cc in child_children:
        cc_children = get_children(cc)
        grandchildren.extend(cc_children)
    print(f"  Child {child} (balance={people[child]}):")
    print(f"    Children: {child_children}")
    print(f"    Grandchildren ({len(grandchildren)}): {grandchildren}")

